       "tex": "\\hat{u} = \\frac{2\\hat{i} + 2\\hat{j} + 2\\hat{k}}{\\sqrt{2^2 + 2^2 + 2^2}} = \\frac{\\hat{i} + \\hat{j} + \\hat{k}}{\\sqrt{3}}"
