      {
       "t": "p",
       "text": "At $(1, 2)$:"
      },
      {
       "t": "math",
       "tex": "\\nabla f(1, 2) = (2(1) + 2)\\hat{i} + (1 + 4(2))\\hat{j} = 4\\hat{i} + 9\\hat{j}"
      },
      {
       "t": "ol",
       "start": 2,
       "items": [
        "Unit vector in direction making $30^\\circ$ with $+x$ axis:"
       ]
      },
      {
       "t": "math",
       "tex": "\\hat{u} = \\cos 30^\\circ\\hat{i} + \\sin 30^\\circ\\hat{j} = \\frac{\\sqrt{3}}{2}\\hat{i} + \\frac{1}{2}\\hat{j}"
      },
      {
       "t": "ol",
       "start": 3,
       "items": [
        "Compute directional derivative:"
       ]
      },
      {
       "t": "math",
       "tex": "D_{\\hat{u}} f = \\nabla f(1, 2)\\cdot\\hat{u} = (4\\hat{i} + 9\\hat{j})\\cdot\\left(\\frac{\\sqrt{3}}{2}\\hat{i} + \\frac{1}{2}\\hat{j}\\right) = 4\\left(\\frac{\\sqrt{3}}{2}\\right) + 9\\left(\\frac{1}{2}\\right) = 2\\sqrt{3} + 4.5 \\approx 3.464 + 4.5 = 7.964"
      }
